gHJ(){return"even"},
gHK(){return"odd"},
ake(a,b,c){return"Look at the parity: "+a+". The result is "+b+", so "+c+" doesn't fit. I rule it out."},
akd(a,b,c,d){return"Look only at the units digit: "+a+". The result therefore ends in "+b+", and "+c+" ends in "+d+". I rule it out."},
akc(a,b){return"Check by going back: "+a+". That doesn't give back the right number, so "+b+" doesn't fit. I rule it out."},
akb(a){return"Only "+a+" is left: it is the result."},
ael(a){return"I take "+a+" away: it isn't the right number of cubes."},
aek(a){return"Only "+a+" is left: it is the right number of cubes."},
